SELECT COALESCE(SUM(pay_order_paid_amount), 0)
FROM pay_order


        AND pay_order_status IN
        #{s}

    AND pay_order_pay_time >= #{start}
    AND pay_order_pay_time < #{end}

SELECT COALESCE(SUM(pay_order_refund_amount), 0)
FROM pay_order

    AND pay_order_updated_at >= #{start}
    AND pay_order_updated_at < #{end}

SELECT COUNT(*)
FROM pay_order

    AND pay_order_created_at >= #{start}
    AND pay_order_created_at < #{end}

SELECT COUNT(*)
FROM pay_order
WHERE pay_order_refund_amount > 0
AND pay_order_updated_at >= #{start}
AND pay_order_updated_at < #{end}

SELECT COUNT(*)
FROM pay_order
WHERE pay_order_status = 'PENDING'
AND pay_order_created_at >= #{start}
AND pay_order_created_at < #{end}
AND pay_order_created_at < #{deadline}

